#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Fix locked Near SPH/CYL/AXIS in Refraction"
echo "=================================================="
echo ""
echo "Bug: after the ADD-power feature, Near SPH/CYL/AXIS"
echo "became permanently read-only (auto = Dist SPH + ADD),"
echo "with NO way to enter/override them manually -- not"
echo "even for the doctor after unlocking a completed"
echo "assessment. Patients with no Distance vision (e.g."
echo "Ashutosh Kumar Negi) could never get a Near value at"
echo "all, since there was nothing to add ADD power to."
echo ""
echo "Fix: Near SPH/CYL/AXIS are editable fields again."
echo "Dist+ADD still auto-fills them as a convenience"
echo "default, but tapping the field always opens the"
echo "picker so it can be set or corrected directly."
echo ""

TARGET="app/(main)/optometry/[id]/optometry-workspace.js"

if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi

echo "Backing up current file to a .bak copy ..."
cp "$TARGET" "$TARGET.bak"

echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"

echo ""
echo "Verifying JS syntax ..."
node --check "$TARGET" && echo "  Syntax OK"

echo ""
echo "Done. Review the diff with:"
echo '  git diff "app/(main)/optometry/[id]/optometry-workspace.js"'
echo ""
echo "NOTE: This is a client-code-only fix -- no DB schema or"
echo "migration changes needed."
echo ""
echo "To fix Ashutosh Kumar Negi's existing record specifically:"
echo "open his completed Optometry assessment as the doctor"
echo "(record is unlocked/editable), go to Final Rx tab, tap"
echo "the Near SPH field for RE, and enter the correct value"
echo "directly -- it will now accept manual entry."
